def max_energy(beads):
    n = len(beads)
    dp = [[0] * n for _ in range(n)]

    # Initialize the dp array for the base case
    for i in range(n):
        dp[i][i] = beads[i]
        if i < n - 1:
            dp[i][i + 1] = beads[i] * beads[i + 1]

    # Fill the dp array by considering all subproblems
    for length in range(2, n):
        for i in range(n - length + 1):
            j = i + length
            dp[i][j] = dp[i][j - 1]
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] * dp[k][j])

    return dp[0][n - 1]
