def next_permutation(perm: list) -> bool:
    # Find the first element that is smaller than the number after it
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            break
    # If no such element is found, the permutation is the last one
    else:
        return False

    # Find the smallest element greater than perm[i] to the right of perm[i]
    for j in range(len(perm) - 1, i, -1):
        if perm[j] > perm[i]:
            break

    # Swap perm[i] and perm[j]
    perm[i], perm[j] = perm[j], perm[i]

    # Reverse the order of numbers after perm[i]
    perm[i + 1:] = reversed(perm[i + 1:])

    return True
